 dirs4=[(-1,0),(1,0),(0,-1),(0,1)]
 dirs8=[(i,j) for i in (-1,0,1) for j in (-1,0,1) if (i,j)!=(0,0)]
 dirs=dirs4 if conn==4 else dirs8
 while q:
  r,c=q.popleft()
  for dr,dc in dirs:
   nr,nc=r+dr,c+dc
   if 0<=nr<h and 0<=nc<w and g[nr,nc]==8 and (nr,nc) not in reach:
    reach.add((nr,nc)); q.append((nr,nc))
 out=g.copy()
